import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"PDC","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/corelib/pdc.md","filePath":"en/modules/corelib/pdc.md","lastUpdated":0}`),a={name:`en/modules/corelib/pdc.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="pdc" tabindex="-1">PDC <a class="header-anchor" href="#pdc" aria-label="Permalink to “PDC”">​</a></h1><p>PDC means Bukkit <code>PersistentDataContainer</code>. CoreLib uses it to store structured module state on items, block states, and other persistent holders. EmakiCooking now prefers block-entity PDC for station state and falls back to <code>data/stations/</code> YAML only for non-<code>TileState</code> station anchors.</p><h2 id="why-pdc-matters" tabindex="-1">Why PDC matters <a class="header-anchor" href="#why-pdc-matters" aria-label="Permalink to “Why PDC matters”">​</a></h2><p>Lore is display text, not reliable data. PDC is more suitable for real state such as item IDs, strengthening stars, forge quality, gem sockets, set pieces, skill IDs, and attribute payloads.</p><h2 id="what-each-module-writes" tabindex="-1">What each module writes <a class="header-anchor" href="#what-each-module-writes" aria-label="Permalink to “What each module writes”">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Written data</th><th>Notes</th></tr></thead><tbody><tr><td>EmakiItem</td><td>Item id, set id, base attributes, skill bindings, version number</td><td>Item identity and base configuration data.</td></tr><tr><td>EmakiForge</td><td>Forge layer, quality, material contribution, recipe id</td><td>Structured record of a forge result.</td></tr><tr><td>EmakiStrengthen</td><td>Star level, forge-mark state, protection state, strengthen attributes, milestones</td><td>Strengthening progress and penalty state.</td></tr><tr><td>EmakiGem</td><td>Socket list, gem id, gem level, upgrade state</td><td>Full state of the gem system.</td></tr><tr><td>EmakiAttribute</td><td>Attribute payload, attribute source markers</td><td>Attribute values granted by equipment.</td></tr><tr><td>EmakiSkills</td><td>Player skill slots, skill levels, trigger bindings</td><td>Usually stored in player data files rather than item PDC.</td></tr><tr><td>EmakiCooking</td><td>World station state, block-entity PDC keys such as <code>emakicooking:station_state</code></td><td>Prefers the station anchor&#39;s block-entity PDC; plain blocks fall back to <code>data/stations/</code>, with a coordinate index used for chunk recovery.</td></tr></tbody></table><h2 id="key-naming-no-dots" tabindex="-1">Key naming: no dots <a class="header-anchor" href="#key-naming-no-dots" aria-label="Permalink to “Key naming: no dots”">​</a></h2><p>Every Emaki PDC key joins its levels with underscores (<code>_</code>) and never with dots (<code>.</code>):</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>emaki_attribute:item_attributes_source_index</span></span>
<span class="line"><span>emakiforge:forge_quality_id</span></span>
<span class="line"><span>emaki:item_operations</span></span>
<span class="line"><span>emaki:item_state_meta_revision</span></span></code></pre></div><p>Bukkit&#39;s <code>YamlConfiguration</code> treats <code>.</code> as a path separator, so a dotted key cannot be expressed in YAML at all — quoting and backslash escaping both fail because the split happens while the YAML is loaded. Flat keys can be written directly into any Bukkit YAML config, which is what third-party plugins need.</p><div class="warning custom-block"><p class="custom-block-title">This was a breaking change</p><p>Earlier versions joined with dots (<code>emakiforge:forge.quality_id</code>). Existing items, players, and entities still carry the old keys; the plugin migrates them automatically, see <a href="#legacy-key-migration">Legacy key migration</a>.</p></div><p>If you are writing an extension module, keep dots out of both partition paths and field names. <code>PdcPartition</code> joins partition and field with <code>_</code>, but it does not replace dots you pass in yourself.</p><h2 id="legacy-key-migration" tabindex="-1">Legacy key migration <a class="header-anchor" href="#legacy-key-migration" aria-label="Permalink to “Legacy key migration”">​</a></h2><p>There are two migration paths and normally you do not need to do anything.</p><p><strong>Lazy conversion (automatic)</strong>: on read, a module tries the flat key first and falls back to the legacy dotted key; on a hit it writes the flat key in place and removes the old one. Player join additionally runs one full conversion over the player&#39;s own PDC, which covers write-only mirror keys that a read path would never touch.</p><p><strong>Manual command (speed-up and troubleshooting)</strong>:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/emakicorelib pdc-convert &lt;players|containers|entities|all&gt; [--dry-run]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Scope</th><th>Coverage</th></tr></thead><tbody><tr><td><code>players</code></td><td>Online players&#39; inventory, armor slots, off-hand, ender chest (including nested shulker boxes), plus the player&#39;s own PDC</td></tr><tr><td><code>containers</code></td><td>Items inside container blocks in loaded chunks</td></tr><tr><td><code>entities</code></td><td>Entity PDC in loaded chunks, plus items on dropped items, item frames, and mob equipment slots</td></tr><tr><td><code>all</code></td><td>Everything above</td></tr></tbody></table><p>Requires <code>emakicorelib.admin</code>. Add <code>--dry-run</code> to count without writing. The command is idempotent: a second run should report 0 conversions. Scanning is batched per loaded chunk and never force-loads chunks.</p><div class="important custom-block"><p class="custom-block-title">What the command cannot reach</p><p>Offline players&#39; inventories and their own PDC (that data lives in playerdata NBT files), and containers or entities in unloaded chunks. Those rely on lazy conversion and are handled automatically on the next read after the player logs in or the chunk loads. No manual action is needed.</p></div><div class="danger custom-block"><p class="custom-block-title">Config files need a manual check</p><p>The converter only touches PDC data and <strong>never edits config files</strong>. Two things need updating by hand:</p><ul><li>Full key names written directly in your own <code>pdc_match</code> config, such as <code>&quot;emakiforge:forge.quality_id&quot;</code>.</li><li>Variable names derived from PDC keys and used in expressions or matchers: <code>pdc_&lt;namespace&gt;_&lt;key&gt;</code> and <code>item_pdc_&lt;namespace&gt;_&lt;key&gt;</code>.</li></ul><p>EmakiStrengthen&#39;s Forge variables are the exception: their dotted spelling is kept as an alias and needs no change.</p></div><h2 id="namespace-rule" tabindex="-1">Namespace rule <a class="header-anchor" href="#namespace-rule" aria-label="Permalink to “Namespace rule”">​</a></h2><p>Each module should write its own namespace or source and avoid overwriting other module data. For example, Gem should not clear Strengthen data, and Strengthen should not clear Forge data.</p><h2 id="how-pdc-relates-to-assembly" tabindex="-1">How PDC relates to Assembly <a class="header-anchor" href="#how-pdc-relates-to-assembly" aria-label="Permalink to “How PDC relates to Assembly”">​</a></h2><p>PDC holds the real data; Assembly renders it into the final presentation:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>module writes PDC → CoreLib reads every layer → Assembly renders → final lore / name / attributes</span></span></code></pre></div><p>Which means:</p><ul><li>Lore is an output, not an input. Never derive data back from lore.</li><li>Editing lore does not change real state.</li><li>Refreshing an item makes CoreLib re-read PDC and rebuild the presentation.</li></ul><h2 id="advice" tabindex="-1">Advice <a class="header-anchor" href="#advice" aria-label="Permalink to “Advice”">​</a></h2><p>Do not manually edit PDC in production. Use module commands or APIs to inspect, clear, or refresh state.</p><p>Most of the time you never edit PDC by hand. What matters operationally:</p><ul><li><strong>Do not let other plugins clean up PDC on Emaki items.</strong> Some &quot;item cleaner&quot; plugins strip custom NBT data.</li><li><strong>Do not rewrite PDC-carrying gear through an incompatible plugin.</strong> Some item editors build a brand-new ItemStack and lose the original PDC.</li><li><strong>Use inspect / dump style commands when debugging gear.</strong> Do not judge an item&#39;s health from its lore alone.</li><li><strong>Prefer a module&#39;s own clear / reset command</strong> to wipe that module&#39;s state. Deleting PDC keys by hand can leave data inconsistent.</li><li><strong>Back up important gear</strong> before any destructive testing.</li></ul><h2 id="notes-for-developers" tabindex="-1">Notes for developers <a class="header-anchor" href="#notes-for-developers" aria-label="Permalink to “Notes for developers”">​</a></h2><h3 id="use-your-own-namespace" tabindex="-1">Use your own namespace <a class="header-anchor" href="#use-your-own-namespace" aria-label="Permalink to “Use your own namespace”">​</a></h3><div class="language-java"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NamespacedKey key </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> NamespacedKey</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(yourPlugin, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your_data_key&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Never write into another module&#39;s namespace.</p><h3 id="keep-the-data-small" tabindex="-1">Keep the data small <a class="header-anchor" href="#keep-the-data-small" aria-label="Permalink to “Keep the data small”">​</a></h3><p>Item PDC travels with the item over the network, so large payloads cost performance:</p><ul><li>Store only the identifiers and values you need.</li><li>Keep complex data in external files and store just a reference id in PDC.</li><li>Put a sensible cap on list data.</li></ul><h3 id="version-your-structures" tabindex="-1">Version your structures <a class="header-anchor" href="#version-your-structures" aria-label="Permalink to “Version your structures”">​</a></h3><div class="language-java"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">container.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(versionKey, PersistentDataType.INTEGER, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>A version number lets you tell whether a migration is needed when the format changes.</p><h3 id="let-assembly-generate-the-presentation" tabindex="-1">Let Assembly generate the presentation <a class="header-anchor" href="#let-assembly-generate-the-presentation" aria-label="Permalink to “Let Assembly generate the presentation”">​</a></h3><p>Build presentation through Assembly / Renderer rather than concatenating lore directly. That keeps multi-module ordering consistent, avoids duplicate or missing entries, and supports templating and localisation.</p><h3 id="read-other-modules-through-their-own-api" tabindex="-1">Read other modules through their own API <a class="header-anchor" href="#read-other-modules-through-their-own-api" aria-label="Permalink to “Read other modules through their own API”">​</a></h3><p>Prefer the <strong>owning module&#39;s API module</strong>. Do not depend on internal keys, and do not look for an entry point in CoreLib:</p><div class="language-java"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// Recommended: go through the owning module&#39;s API</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// Attributes → EmakiAttributeApi (emaki.jiuwu.craft.attribute.api)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EmakiResult&lt;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">Double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; attack </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> EmakiAttributeApi.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">catalog</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">attributeValue</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(player, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;physical_attack&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// Not recommended: reading an internal PDC key directly</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NamespacedKey internalKey </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> NamespacedKey</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(attributePlugin, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;internal_key&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Internal keys may change between versions; the API stays stable.</p><h2 id="data-lifecycle" tabindex="-1">Data lifecycle <a class="header-anchor" href="#data-lifecycle" aria-label="Permalink to “Data lifecycle”">​</a></h2><table tabindex="0"><thead><tr><th>Event</th><th>PDC behaviour</th></tr></thead><tbody><tr><td>Item creation</td><td>The module writes its initial PDC data.</td></tr><tr><td>Item operation (strengthen / forge / inlay)</td><td>The owning module updates its own PDC data.</td></tr><tr><td>Item refresh</td><td>CoreLib reads PDC and rebuilds the presentation.</td></tr><tr><td>Item dropped or stored</td><td>PDC data is saved along with the item.</td></tr><tr><td>Server restart</td><td>PDC data persists with the item and is not lost.</td></tr><tr><td>Item copied by another plugin</td><td>Depends on the copy method; <code>ItemStack.clone()</code> preserves PDC.</td></tr><tr><td>Item edited by an NBT editor</td><td>May break the data structure; editing by hand is discouraged.</td></tr></tbody></table><h2 id="where-shared-pdc-contracts-live-now" tabindex="-1">Where shared PDC contracts live now <a class="header-anchor" href="#where-shared-pdc-contracts-live-now" aria-label="Permalink to “Where shared PDC contracts live now”">​</a></h2><p>CoreLib used to host some cross-module PDC contracts. Those contracts have been moved to the owning API / protocol modules. New code should use the right-hand column:</p><table tabindex="0"><thead><tr><th>Data</th><th>Authoritative entry point</th><th>Legacy CoreLib entry point</th></tr></thead><tbody><tr><td>Equipment attribute PDC contract</td><td><code>EmakiAttributeApi</code> (in the <code>EmakiAttributeApi</code> module)</td><td><code>PdcAttributeGateway</code> and <code>EmakiAttributeBridge</code> were removed in CoreLib <code>4.6.7</code></td></tr><tr><td>Equipment skill PDC read/write</td><td><code>EquipmentSkillPdcCodec</code> (package <code>emaki.jiuwu.craft.skills.api.pdc</code> in the <code>EmakiSkillsApi</code> module)</td><td><code>SkillPdcGateway</code> was removed in CoreLib <code>4.6.7</code></td></tr></tbody></table><p>These classes no longer exist on the CoreLib side; new code must use the right-hand column.</p><p>When you store structured data, keep a version number so you can migrate later. CoreLib&#39;s <code>SnapshotCodec</code> provides encoding, decoding, and version compatibility support.</p>`,55)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};